SELECT     concat(abs(LPAD(CAST(SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) AS INT), 2, '0')), '月') AS month,     ROUND(CAST(t1.year_lend AS DECIMAL(38, 2)) / 100000000, 2) AS bnxfje,     ROUND(CAST(COALESCE(t2.year_lend, 0) AS DECIMAL(38, 2)) / 100000000, 2) AS snxfje FROM     (SELECT         tjzq,         SUM(dytqje) AS year_lend      FROM dws_bus_ft_per_mfm      WHERE SUBSTR(CAST(tjzq AS STRING), 1, 4) = CAST(#{ssnd} AS STRING)      and tqlx not in (97,6,5,60,62,34,70,54,15,1,68,73,59)      GROUP BY tjzq) t1 LEFT JOIN     (SELECT         tjzq,         SUM(dytqje) AS year_lend      FROM dws_bus_ft_per_mfm      WHERE SUBSTR(CAST(tjzq AS STRING), 1, 4) = CAST(#{ssnd} - 1 AS STRING)      and tqlx not in (97,6,5,60,62,34,70,54,15,1,68,73,59)      GROUP BY tjzq) t2 ON SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) = SUBSTR(CAST(t2.tjzq AS STRING), 5, 2) ORDER BY CAST(SUBSTR(CAST(t1.tjzq AS STRING), 5, 2) AS INT)
